<script setup>
// Review-only prototype. Not imported by the production router; no API calls.
import {computed,reactive,ref} from 'vue';
import {ElMessage} from 'element-plus';
import {Document,Warning,Van,Box} from '@element-plus/icons-vue';
import {inventorySupplyPlan} from '../../src/shared/inventory-supply-plan.js';
import {shanghaiDateTimeText} from '../admin/utils/shanghai-date.js';
import ProductImagePreview from '../admin/components/ProductImagePreview.vue';
import OrderWorkModeSwitch from '../orders/components/OrderWorkModeSwitch.vue';
const now=Date.now(),time=v=>shanghaiDateTimeText(new Date(v).toISOString(),{assumeUtcWhenNaive:true});
const productRows=[{id:490,number:'21-4',name:'钥匙扣 通用 黑色 普通款 皮革/金属 1个',physical:2,demand:28,safety:47,fbp:0},{id:102,number:'8-1',name:'雨刮垫 通用 黑色 普通款 1个',physical:40,demand:10,safety:20,fbp:0},{id:103,number:'76-7',name:'钥匙手绳 TENET 黑色 普通款 1个',physical:4,demand:0,safety:10,fbp:0},{id:104,number:'3-2',name:'车标配件 TENET 银色 1个',physical:1,demand:0,safety:0,fbp:0}];
const products=reactive(productRows.map(p=>({...p}))),batches=reactive([{id:1,productId:102,order:'CG-DEMO-1001',quantity:12,buyer:'采购员 A',purchased:now-72*3600000,stage:'open',courier:'',tracking:''},{id:2,productId:102,order:'CG-DEMO-1002',quantity:6,buyer:'采购员 B',purchased:now-24*3600000,stage:'open',courier:'示例快递',tracking:'DEMO1002'},{id:3,productId:104,order:'CG-DEMO-1003',quantity:5,buyer:'采购员 A',purchased:now-96*3600000,arrived:now-12*3600000,stage:'arrived',courier:'示例快递',tracking:'DEMO1003'}]);
const tab=ref('required'),query=ref(''),searchMode=ref('auto'),scope=ref('all'),updated=ref(now),calculated=ref(now);
const queues=[{key:'required',label:'必须采购',hint:'FBS订单 / 正式FBP申请',unit:'项库存',icon:Document},{key:'advisory',label:'保障补货',hint:'无必须缺口的额外保障',unit:'项库存',icon:Warning},{key:'incoming',label:'采购待到货',hint:'采购确认签收',unit:'个批次',icon:Van},{key:'receiving',label:'到货待验收',hint:'仓库核对数量并入库',unit:'个批次',icon:Box}];
const incoming=id=>batches.filter(b=>b.productId===id&&['open','arrived'].includes(b.stage)).reduce((n,b)=>n+b.quantity,0);
function calculate(p){const gap=Math.max(0,p.demand-p.physical),transit=incoming(p.id);return inventorySupplyPlan({physical_estimate:p.physical,open_order_demand:p.demand,fbp_reserved:0,incoming_quantity:transit,current_incoming:Math.min(gap,transit),current_shortage:Math.max(0,gap-transit),flow_summary:{safety:p.safety},fbp_inventory:{incomplete:false}},[{status:'pending_review',shop_id:1,ozon_sku:'demo-'+p.id,requested_quantity:p.fbp}],{stock_incomplete:false,skus:[{shop_id:1,ozon_sku:'demo-'+p.id,available:0,fbp_target:0,per_set_quantity:1}]});}
const stockRows=computed(()=>products.map(p=>({...p,plan:calculate(p),incoming:incoming(p.id)})));
const attributes=[{key:'category',label:'核心品名',values:['钥匙扣','雨刮垫','钥匙手绳','车标配件']},{key:'brand',label:'汽车品牌',values:['通用','TENET']},{key:'model',label:'车型',values:['T7','T8']},{key:'color',label:'颜色',values:['黑色','银色']},{key:'style',label:'款式',values:['普通款']},{key:'material',label:'材质',values:['皮革','金属']},{key:'process',label:'工艺',values:['LOGO定制']}];
const preciseVisible=ref(false);
const precise=reactive(Object.fromEntries(attributes.map(a=>[a.key,'']))),productName=ref('');
const placeholder=computed(()=>({inventory_id:'完整库存编号，如 21-4',sku:'完整 Ozon SKU 或货号',name:'名称关键词'}[searchMode.value]||'库存编号 / SKU / 货号 / 名称关键词'));
function resetSearch(){query.value='';searchMode.value='auto';productName.value='';for(const a of attributes)precise[a.key]='';updated.value=Date.now();}
const matches=p=>{const q=query.value.trim().toLowerCase();const text=p.name.toLowerCase();const keyword=!q||(searchMode.value==='inventory_id'?p.number.toLowerCase()===q:searchMode.value==='sku'?['demo-'+p.id,'DEMO-OFFER-'+p.id].some(v=>v.toLowerCase()===q):searchMode.value==='name'?text.includes(q):`${p.number} demo-${p.id} DEMO-OFFER-${p.id} ${p.name}`.toLowerCase().includes(q));return keyword&&attributes.every(a=>!precise[a.key]||text.includes(precise[a.key].toLowerCase()))&&(!productName.value.trim()||text.includes(productName.value.trim().toLowerCase()));};
const counts=computed(()=>({required:stockRows.value.filter(p=>p.plan.required_purchase>0).length,advisory:stockRows.value.filter(p=>p.plan.required_purchase===0&&p.plan.optional_purchase>0).length,incoming:batches.filter(b=>b.stage==='open').length,receiving:batches.filter(b=>b.stage==='arrived').length}));
const visibleStocks=computed(()=>stockRows.value.filter(matches).filter(p=>tab.value==='required'?p.plan.required_purchase>0:p.plan.required_purchase===0&&p.plan.optional_purchase>0));
const visibleBatches=computed(()=>batches.filter(b=>b.stage===(tab.value==='incoming'?'open':'arrived')).map(b=>({...b,product:products.find(p=>p.id===b.productId)})).filter(b=>matches(b.product)));
const total=p=>p.plan.required_purchase+p.plan.optional_purchase,age=(stamp)=>((Date.now()-stamp)/86400000).toFixed(1);
const drawer=reactive({visible:false,id:490,view:'detail'}),selected=computed(()=>stockRows.value.find(p=>p.id===drawer.id));
const purchase=reactive({visible:false,id:490,quantity:0,basis:'total'}),arrival=reactive({visible:false,id:0}),logistics=reactive({visible:false,id:0,courier:'',tracking:''}),receipt=reactive({visible:false,id:0,quantity:0,reason:''});
const count=ref(0);
function openDrawer(row,view='detail'){Object.assign(drawer,{visible:true,id:row.id,view});count.value=row.physical;}
function buy(row){Object.assign(purchase,{visible:true,id:row.id,quantity:total(row),basis:'total'});}
function preset(){const p=stockRows.value.find(p=>p.id===purchase.id);purchase.quantity=purchase.basis==='required'?p.plan.required_purchase:total(p);}
function register(){if(!(purchase.quantity>0))return;const id=Math.max(...batches.map(b=>b.id))+1;batches.push({id,productId:purchase.id,order:'CG-DEMO-'+(1000+id),quantity:purchase.quantity,buyer:'当前采购员',purchased:Date.now(),stage:'open',courier:'',tracking:''});purchase.visible=false;updated.value=Date.now();ElMessage.success('演示采购已登记，净缺口已更新');}
function startLogistics(row){Object.assign(logistics,{visible:true,id:row.id,courier:row.courier,tracking:row.tracking});}
function saveLogistics(){Object.assign(batches.find(b=>b.id===logistics.id),{courier:logistics.courier,tracking:logistics.tracking});logistics.visible=false;}
function confirmArrival(){const b=batches.find(b=>b.id===arrival.id);b.stage='arrived';b.arrived=Date.now();arrival.visible=false;updated.value=Date.now();ElMessage.success('已到货，等待仓库验收；本地实物未增加');}
function receive(row){Object.assign(receipt,{visible:true,id:row.id,quantity:row.quantity,reason:''});}
function postReceipt(){const b=batches.find(b=>b.id===receipt.id);if(!(receipt.quantity>0)||receipt.quantity>b.quantity)return;if(receipt.quantity!==b.quantity&&!receipt.reason.trim())return ElMessage.warning('数量不同，请填写差异说明');products.find(p=>p.id===b.productId).physical+=receipt.quantity;b.quantity-=receipt.quantity;if(!b.quantity)b.stage='received';receipt.visible=false;updated.value=Date.now();ElMessage.success('按实际验收数量入库；未验收的剩余量继续保留');}
function stocktake(){products.find(p=>p.id===drawer.id).physical=count.value;drawer.visible=false;updated.value=Date.now();}
const selectedRows=ref([]),bulk=reactive({visible:false,rows:[],query:''});
const bulkResults=computed(()=>products.filter(p=>!bulk.rows.some(r=>r.id===p.id)&&(!bulk.query.trim()||`${p.number} ${p.name}`.includes(bulk.query.trim()))));
function addBulk(p){bulk.rows.push({...p,quantity:Math.max(1,total(stockRows.value.find(r=>r.id===p.id))),amount:0});}
function openBulk(){bulk.rows=[];selectedRows.value.forEach(addBulk);bulk.query='';bulk.visible=true;}
function registerBulk(){if(!bulk.rows.length||bulk.rows.some(r=>!Number.isSafeInteger(r.quantity)||r.quantity<1||!(r.amount>0)))return ElMessage.warning('请填写每项采购件数和实际货款');for(const r of bulk.rows){const id=Math.max(...batches.map(b=>b.id))+1;batches.push({id,productId:r.id,order:'CG-DEMO-'+(1000+id),quantity:r.quantity,buyer:'当前采购员',purchased:Date.now(),stage:'open',courier:'',tracking:''});}bulk.visible=false;updated.value=Date.now();ElMessage.success('演示批量采购已登记');}
const productBatches=computed(()=>batches.filter(b=>b.productId===drawer.id));
</script>
<template>
 <main class="queue-preview">
  <div class="preview-notice">订单处理 · 库存管理设计预览 <span>演示数据，所有操作仅在本页模拟</span></div>
  <section class="queue-search" aria-label="库存搜索及操作">
   <div class="search-left"><label>库存范围<el-select v-model="scope"><el-option label="全部库存" value="all"/></el-select></label><label>搜索方式<el-select v-model="searchMode" aria-label="搜索方式"><el-option label="综合搜索" value="auto"/><el-option label="库存编号精确" value="inventory_id"/><el-option label="SKU／货号精确" value="sku"/><el-option label="产品名称模糊" value="name"/></el-select></label><label class="keyword">搜索内容<el-input v-model="query" aria-label="搜索内容" :placeholder="placeholder" clearable/></label><el-popover v-model:visible="preciseVisible" trigger="click" placement="bottom-start" :width="'min(660px,94vw)'"><template #reference><el-button plain>精确搜索</el-button></template><div class="preview-precise-fields"><label v-for="a in attributes" :key="a.key">{{a.label}}<el-select v-model="precise[a.key]" :aria-label="a.label" filterable clearable placeholder="全部"><el-option v-for="v in a.values" :key="v" :label="v" :value="v"/></el-select></label><label>产品名称<el-input v-model="productName" aria-label="产品名称" placeholder="补充名称关键词" clearable/></label><el-button type="primary" @click="preciseVisible=false;updated=Date.now()">应用筛选</el-button></div></el-popover><el-button type="primary" @click="updated=Date.now()">查询</el-button><el-button @click="resetSearch">重置</el-button><el-button plain @click="ElMessage.info('保留本地库存异常和资料待核实入口；与到货验收分开处理')">库存异常 <el-tag type="info" size="small">1</el-tag></el-button></div>
   <div class="search-right"><div class="queue-time"><span>核算 {{time(calculated)}}</span><small>读取 {{time(updated)}}</small></div><el-button @click="updated=Date.now()">刷新库存需求</el-button><el-button @click="calculated=Date.now();updated=Date.now()">重新核算</el-button><OrderWorkModeSwitch mode="inventory" @change="ElMessage.info('打印模式沿用已上线的订单处理界面')"/></div>
  </section>
  <div class="queue-cards"><button v-for="q in queues" :key="q.key" :class="['queue-card',{active:tab===q.key}]" @click="tab=q.key"><el-icon><component :is="q.icon"/></el-icon><div><b>{{q.label}}</b><small>{{q.hint}}</small></div><strong>{{counts[q.key]}} <small>{{q.unit}}</small></strong></button></div>
  <template v-if="['required','advisory'].includes(tab)">
   <div class="left-actions"><el-button type="primary" :disabled="!selectedRows.length" @click="openBulk">批量登记采购{{selectedRows.length?`（${selectedRows.length}）`:''}}</el-button></div><p class="queue-caption">{{tab==='required'?'先满足真实订单和正式备货申请；保障补货可按经营判断一并采购。':'本队列仅展示没有必须缺口、仍需额外保障补货的库存。'}} 现货与采购在途已抵扣，同一件货源只计算一次。</p>
   <el-table @selection-change="value=>selectedRows=value" :data="visibleStocks" border row-key="id" empty-text="货源已覆盖，当前没有新的采购缺口" aria-label="采购需求">
    <el-table-column type="selection" width="45"/><el-table-column label="库存商品" min-width="280"><template #default="{row}"><div class="stock-product"><ProductImagePreview size="portrait"/><div><b>{{row.name}}</b><small>库存 ID：{{row.number}}</small><el-button plain size="small" @click="openDrawer(row)">库存详情</el-button></div></div></template></el-table-column>
    <el-table-column label="本地实物 / 采购在途" min-width="190"><template #default="{row}"><div class="stock-resources"><b>本地实物 {{row.physical}} 件</b><b>采购在途 {{row.incoming}} 件</b><div class="left-actions"><el-button plain size="small" @click="openDrawer(row,'count')">核对实物</el-button><el-button plain size="small" @click="openDrawer(row,'batches')">采购批次</el-button></div></div></template></el-table-column>
    <el-table-column label="三类净缺口" min-width="260"><template #default="{row}"><div class="need-lines"><span><el-button link type="primary" @click="openDrawer(row)">FBS订单</el-button><b>{{row.plan.required_fbs}} 件 · 必须</b></span><span><el-button link type="primary" @click="openDrawer(row)">正式FBP申请</el-button><b>{{row.plan.required_fbp?`${row.plan.required_fbp} 件 · 必须`:'无申请缺口'}}</b></span><span><el-button link type="primary" @click="openDrawer(row)">本地保障</el-button><b>{{row.plan.optional_local}} 件 · 额外补货</b></span></div></template></el-table-column>
    <el-table-column label="本次采购建议" min-width="245"><template #default="{row}"><div class="purchase-summary"><b :class="{must:row.plan.required_purchase>0}">必须采购 {{row.plan.required_purchase}} 件</b><span>可选保障补货 {{row.plan.optional_purchase}} 件</span><strong>建议总采购 {{total(row)}} 件</strong><small>已抵扣现货与在途，不再重复相加</small></div></template></el-table-column>
    <el-table-column label="处理" width="135"><template #default="{row}"><el-button type="primary" @click="buy(row)">登记采购</el-button></template></el-table-column>
   </el-table>
  </template>
  <template v-else>
   <div class="left-actions"><el-button type="primary" :disabled="!selectedRows.length" @click="openBulk">批量登记采购{{selectedRows.length?`（${selectedRows.length}）`:''}}</el-button></div><p class="queue-caption">{{tab==='incoming'?'按未到货采购批次跟踪；采购超过2天标红。确认到货只转入待验收，不增加本地库存。':'采购已确认到货，由仓库核对实际数量并登记入库。与账面异常盘点分开处理。'}}</p>
   <el-table :data="visibleBatches" border row-key="id" :aria-label="tab==='incoming'?'采购待到货':'到货待验收'" empty-text="当前没有待处理批次">
    <el-table-column label="库存商品" min-width="275"><template #default="{row}"><div class="stock-product"><ProductImagePreview size="portrait"/><div><b>{{row.product.name}}</b><small>库存 ID：{{row.product.number}}</small><el-button plain size="small" @click="openDrawer(row.product)">库存详情</el-button></div></div></template></el-table-column>
    <el-table-column label="采购批次 / 人员" min-width="190"><template #default="{row}"><b>{{row.order}}</b><p>{{row.buyer}}</p><small>本地实物 {{row.product.physical}} 件</small></template></el-table-column>
    <el-table-column label="数量" width="120"><template #default="{row}"><b>{{row.quantity}} 件</b><p>{{tab==='incoming'?'待到货':'待验收'}}</p></template></el-table-column>
    <el-table-column :label="tab==='incoming'?'采购时间 / 等待':'采购 / 到货时间'" min-width="215"><template #default="{row}"><span>{{time(row.purchased)}}</span><p v-if="tab==='incoming'" :class="{overdue:Date.now()-row.purchased>48*3600000}">已采购 {{age(row.purchased)}} 天{{Date.now()-row.purchased>48*3600000?' · 超过2天':''}}</p><template v-else><p>到货 {{time(row.arrived)}}</p><small>已到货 {{age(row.arrived)}} 天</small></template></template></el-table-column>
    <el-table-column label="物流 / 核对" min-width="205"><template #default="{row}"><div class="stock-resources"><span>{{row.courier||'快递待填写'}} {{row.tracking}}</span><el-button v-if="tab==='incoming'" plain size="small" @click="startLogistics(row)">填写物流</el-button><el-button v-else plain size="small" @click="openDrawer(row.product,'count')">核对实物</el-button></div></template></el-table-column>
    <el-table-column label="处理" width="145"><template #default="{row}"><el-button v-if="tab==='incoming'" type="primary" @click="Object.assign(arrival,{visible:true,id:row.id})">确认到货</el-button><el-button v-else type="primary" @click="receive(row)">登记入库</el-button></template></el-table-column>
   </el-table>
  </template>
  <el-drawer v-model="drawer.visible" title="库存详情" size="min(650px,95vw)"><template v-if="selected"><h3>{{selected.name}}</h3><el-radio-group v-model="drawer.view"><el-radio-button value="detail">库存流转</el-radio-button><el-radio-button value="count">核对实物</el-radio-button><el-radio-button value="batches">采购批次</el-radio-button></el-radio-group><el-descriptions :column="2" border class="detail-grid"><el-descriptions-item label="本地实物">{{selected.physical}} 件</el-descriptions-item><el-descriptions-item label="采购在途">{{selected.incoming}} 件</el-descriptions-item><el-descriptions-item label="FBS待发需求">{{selected.demand}} 件</el-descriptions-item><el-descriptions-item label="本地保障目标">{{selected.safety}} 件</el-descriptions-item></el-descriptions><template v-if="drawer.view==='count'"><p>仅校准本地实物；采购在途和FBP官方库存不计入。</p><el-input-number v-model="count" :min="0" :precision="0" aria-label="本地实物数量"/><el-button type="primary" @click="stocktake">保存本地盘点</el-button></template><template v-else-if="drawer.view==='batches'"><el-table :data="productBatches"><el-table-column prop="order" label="批次"/><el-table-column prop="quantity" label="待处理数量"/><el-table-column label="状态"><template #default="{row}">{{{open:'待到货',arrived:'待验收',received:'已入库'}[row.stage]}}</template></el-table-column></el-table></template><template v-else><p>现货 / 采购在途 → FBS订单 → 正式FBP申请 → 可选保障</p><p class="purchase-summary"><strong>本次净采购：必须 {{selected.plan.required_purchase}} ＋ 保障 {{selected.plan.optional_purchase}} ＝ 建议总量 {{total(selected)}} 件</strong></p><p>FBP客户订单直接消耗官方仓可用库存，不进入上述本地采购池。</p></template></template></el-drawer>
  <el-dialog v-if="bulk.visible" v-model="bulk.visible" title="批量登记采购" width="min(1200px,96vw)" append-to-body :close-on-click-modal="false"><p>演示采购表：可移除、加货；关闭库存详情后返回本表，填写内容保留。</p><el-input v-model="bulk.query" placeholder="搜索其他库存编号 / 名称加入采购" clearable/><div class="left-actions" style="margin:12px 0"><el-button v-for="p in bulkResults" :key="p.id" size="small" @click="addBulk(p)">加入 {{p.number}} {{p.name}}</el-button></div><el-table :data="bulk.rows" border><el-table-column label="库存商品" min-width="280"><template #default="{row}"><b>{{row.name}}</b><p>{{row.number}}</p><el-button size="small" @click="openDrawer(row)">库存详情</el-button></template></el-table-column><el-table-column label="采购件数" width="180"><template #default="{row}"><el-input-number v-model="row.quantity" :min="1" :precision="0"/></template></el-table-column><el-table-column label="实际货款（元）" width="180"><template #default="{row}"><el-input-number v-model="row.amount" :min="0" :precision="2"/></template></el-table-column><el-table-column label="操作" width="90"><template #default="{row}"><el-button type="danger" plain size="small" @click="bulk.rows=bulk.rows.filter(r=>r!==row)">移除</el-button></template></el-table-column></el-table><template #footer><el-button @click="bulk.visible=false">取消</el-button><el-button type="primary" @click="registerBulk">确认批量登记采购</el-button></template></el-dialog>
  <el-dialog v-model="purchase.visible" title="登记采购" width="min(520px,94vw)"><p>先核对本次采购目标：</p><el-radio-group v-model="purchase.basis" @change="preset"><el-radio value="total">按建议总量（含可选保障）</el-radio><el-radio value="required" :disabled="!stockRows.find(p=>p.id===purchase.id)?.plan.required_purchase">只处理必须缺口</el-radio></el-radio-group><el-form label-position="top"><el-form-item label="本次实际采购数量"><el-input-number v-model="purchase.quantity" :min="1" :precision="0" aria-label="采购数量"/></el-form-item></el-form><template #footer><el-button @click="purchase.visible=false">取消</el-button><el-button type="primary" @click="register">确认登记采购</el-button></template></el-dialog>
  <el-dialog v-model="logistics.visible" title="填写物流" width="min(460px,94vw)"><el-form label-position="top"><el-form-item label="快递公司"><el-input v-model="logistics.courier"/></el-form-item><el-form-item label="快递单号"><el-input v-model="logistics.tracking"/></el-form-item></el-form><template #footer><el-button @click="logistics.visible=false">取消</el-button><el-button type="primary" @click="saveLogistics">保存物流</el-button></template></el-dialog>
